func pageIsArchivedForGuard(ctx, db, pageID, logger) (archived, checked bool) {
	var status string
	if err := db.QueryRowContext(ctx, `SELECT COALESCE(status, '') FROM pages WHERE id = $1`, pageID).Scan(&status); err != nil {
		// sql.ErrNoRows lands here too, and correctly.
		logger.Warn("could not read pages.status; guard stands down", ...)
		return false, false
	}
	return status == archivedPageStatus, true
}

func resolveDeployTargetPage(ctx, db, collected, logger) (uuid.UUID, string, bool) {
	if id, name, ok := resolveGuardedPage(ctx, db, collected, logger); ok { return id, name, true }
	for _, p := range []string{"page_id", "input_data.page_id"} { ... }
	for _, sp := range []string{"site_id", "input_data.site_id", "site_record.site_id"} { ... resolvePageIDByName ... }
	return uuid.Nil, "", false
}

if pageID, pageName, ok := resolveDeployTargetPage(ctx, params.DB, params.CollectedData, params.Logger); ok {
	archived, checked := pageIsArchivedForGuard(ctx, params.DB, pageID, params.Logger)
	if !checked {
		LogActionError(..., "git_commit", "ARCHIVED_PAGE_GUARD_UNCHECKED", "high", ...)
	}
	if archived {
		reason := fmt.Sprintf("%s: page %s is status=archived; committing it would re-publish a retired page. ...", archivedPageSkipReasonPrefix, pageName)
		LogActionError(..., "ARCHIVED_PAGE_DEPLOY_REFUSED", "warning", reason, ...)
		return GitCommitResult{Success: true, AwaitResponse: false, Metadata: map[string]interface{}{"status": "skipped", "skip_reason": reason, ...}}, nil
	}
}

if newStatus == "deployed" {
	archived, checked := pageIsArchivedForGuard(ctx, params.DB, pageID, params.Logger)
	if !checked { LogActionError(..., "update_page_status", "ARCHIVED_PAGE_GUARD_UNCHECKED", "high", ...) }
	if archived {
		reason := fmt.Sprintf("%s: refused deploy stamp — page is status=archived", archivedPageSkipReasonPrefix)
		LogActionError(..., "ARCHIVED_PAGE_DEPLOY_REFUSED", "warning", reason, ...)
		return map[string]interface{}{"updated": false, "page_id": pageID.String(), "skipped": true, "reason": reason}, nil
	}
}
